style.css:
@-moz-document domain("roblox.com") {
html, body, .bg-science, .main-container, .group-header, #container-main {
        background-image: url('https://imgbox.com') !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
    }

    .content, .section-content, .container-main, .timeline-container, .StandardTemplateContainer {
        background: rgba(25, 25, 25, 0.6) !important;
    }
    
    .game-card-container, .item-card-container {
        background: rgba(35, 35, 35, 0.7) !important;
        border-radius: 8px !important;
    }
}
